{"text":"[Reading 28 lines from start (total: 28 lines, 0 remaining)]\n\n\n\"\"\"\nExecution Worker - CCXT ส่งคำสั่งจริง\n\"\"\"\nimport ccxt\n\nclass ExecutionWorker:\n    def __init__(self, exchange_id='binance', api_key=None, secret=None):\n        self.exchange = getattr(ccxt, exchange_id)({\n            'apiKey': api_key,\n            'secret': secret,\n            'enableRateLimit': True,\n        })\n        \n    def execute(self, symbol, side, amount, price=None):\n        try:\n            if price:\n                order = self.exchange.create_limit_order(symbol, side, amount, price)\n            else:\n                order = self.exchange.create_market_order(symbol, side, amount)\n            print(f\"💸 Executed {side} {amount} {symbol} @ {price or 'MARKET'} - ID {order['id']}\")\n            return order\n        except Exception as e:\n            print(f\"❌ Execution failed: {e}\")\n            return None\n\nif __name__ == \"__main__\":\n    print(\"Execution Worker - Paper trading mode (no real keys)\")\n\n[executed on device: 10_3_6_9 (85294689-03d5-431e-abd5-9e27d4c94814)]"}